"""TEMPORARY harness: runs tests/test_traefik_tools.py without pytest.

The API container has no pip/pytest, so this shim provides the two pieces the
test module uses (the ``pytest.fixture`` decorator and ``monkeypatch``) and
executes every ``test_*`` function. Delete this file after the run.
"""

import inspect
import os
import sys
import tempfile
import types

# --- minimal pytest shim ---------------------------------------------------
fake_pytest = types.ModuleType("pytest")


def fixture(*args, **kwargs):
    def decorator(function):
        function.__is_fixture__ = True
        return function

    if args and callable(args[0]):
        return decorator(args[0])
    return decorator


fake_pytest.fixture = fixture
sys.modules["pytest"] = fake_pytest


class MonkeyPatch:
    """Just enough of pytest's MonkeyPatch for these tests."""

    def __init__(self):
        self._undo = []

    def setattr(self, target, name, value=None, raising=True):
        if isinstance(target, str) and value is None:
            module_name, _, attribute = target.rpartition(".")
            target = sys.modules[module_name]
            name, value = attribute, name
        old = getattr(target, name, None)
        self._undo.append(lambda: setattr(target, name, old))
        setattr(target, name, value)

    def setenv(self, name, value, prepend=None):
        old = os.environ.get(name)
        self._undo.append(
            lambda: (os.environ.pop(name, None) if old is None else os.environ.__setitem__(name, old))
        )
        os.environ[name] = str(value)

    def delenv(self, name, raising=True):
        old = os.environ.pop(name, None)
        if old is not None:
            self._undo.append(lambda: os.environ.__setitem__(name, old))

    def undo(self):
        for callback in reversed(self._undo):
            callback()
        self._undo.clear()


# --- run the suite ---------------------------------------------------------
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import test_traefik_tools as suite  # noqa: E402

failures = []
ran = 0

for name in sorted(dir(suite)):
    if not name.startswith("test_"):
        continue
    function = getattr(suite, name)
    if not callable(function):
        continue
    parameters = list(inspect.signature(function).parameters)
    monkeypatch = MonkeyPatch()
    tmp_dir = tempfile.mkdtemp(prefix="traefik-test-")
    # The autouse fixture of the module.
    suite.isolated_env.__wrapped__(monkeypatch, tmp_dir) if hasattr(
        suite.isolated_env, "__wrapped__"
    ) else suite.isolated_env(monkeypatch, tmp_dir)
    kwargs = {}
    for parameter in parameters:
        if parameter == "monkeypatch":
            kwargs[parameter] = monkeypatch
        elif parameter == "tmp_path":
            kwargs[parameter] = tmp_dir
    ran += 1
    try:
        function(**kwargs)
        print(f"PASS {name}")
    except Exception as ex:  # noqa: BLE001
        failures.append((name, ex))
        print(f"FAIL {name}: {ex}")
    finally:
        monkeypatch.undo()

print(f"\n{ran - len(failures)}/{ran} passed")
sys.exit(1 if failures else 0)

